#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int MOD = 1000000007;

int64 mod_pow(int64 a, int64 e = MOD - 2) {
    int64 r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    int k;
    if (!(cin >> n >> k)) return 0;

    // Factorize n
    vector<pair<int64, int>> factors;
    int64 temp = n;
    for (int64 p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            int cnt = 0;
            while (temp % p == 0) {
                temp /= p;
                ++cnt;
            }
            factors.emplace_back(p, cnt);
        }
    }
    if (temp > 1) factors.emplace_back(temp, 1);

    int64 ans = 1;

    for (auto [prime, exp] : factors) {
        int e = exp;
        vector<vector<int64>> dp(k + 1, vector<int64>(e + 1));
        // dp[step][current_exponent]
        // base: step 0, we start at exponent 'e', value = p^e
        for (int x = 0; x <= e; ++x) {
            dp[0][x] = mod_pow(prime, x);
        }
        // Precompute modular inverses of 1..(e+1)
        vector<int64> inv(e + 2);
        for (int i = 1; i <= e + 1; ++i) inv[i] = mod_pow(i);

        for (int step = 1; step <= k; ++step) {
            vector<int64> prefix(e + 1);
            prefix[0] = dp[step - 1][0];
            for (int x = 1; x <= e; ++x) {
                prefix[x] = (prefix[x - 1] + dp[step - 1][x]) % MOD;
            }
            for (int x = 0; x <= e; ++x) {
                dp[step][x] = prefix[x] * inv[x + 1] % MOD;
            }
        }
        ans = ans * dp[k][e] % MOD;
    }

    cout << ans << "\n";
    return 0;
}
