const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long res = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int k;
    if(!(cin >> n >> k)) return 0;

    // 1. Factorize n
    vector<pair<long long, int>> factors;
    long long temp_n = n;
    for (long long p = 2; p * p <= temp_n; ++p) {
        if (temp_n % p == 0) {
            int cnt = 0;
            while (temp_n % p == 0) {
                temp_n /= p;
                cnt++;
            }
            factors.push_back({p, cnt});
        }
    }
    if (temp_n > 1) {
        factors.push_back({temp_n, 1});
    }

    // 2. Precompute inverses up to max_e + 1 (max exponent is <= 50)
    int max_e = 0;
    for (auto &f : factors) max_e = max(max_e, f.second);
    vector<long long> inv(max_e + 2);
    for (int i = 1; i <= max_e + 1; ++i) {
        inv[i] = modpow(i, MOD - 2);
    }

    long long ans = 1;

    // 3. Process each prime factor independently
    for (auto &f : factors) {
        long long p = f.first;
        int e = f.second; // max exponent

        // dp[j] = expected value of p^j after current number of steps? 
        // No, dp[j] is the probability of being at exponent j?
        // Let's define val[j] = p^j mod MOD.
        // The transition for exponents: from e, go to any x in [0, e] uniformly.
        // Expected value of p^x. 
        // Let F_k(e) be expected value of p^X after k steps starting from exponent e.
        // F_0(e) = p^e.
        // F_k(e) = (1/(e+1)) * sum_{x=0}^e F_{k-1}(x).

        vector<long long> dp(e + 1);
        // Base case: step 0
        long long p_mod = p % MOD;
        long long cur_pow = 1;
        for (int j = 0; j <= e; ++j) {
            dp[j] = cur_pow;
            cur_pow = cur_pow * p_mod % MOD;
        }

        // Iterate k times
        for (int step = 0; step < k; ++step) {
            vector<long long> prefix(e + 1);
            prefix[0] = dp[0];
            for (int j = 1; j <= e; ++j) {
                prefix[j] = (prefix[j-1] + dp[j]) % MOD;
            }
            vector<long long> new_dp(e + 1);
            for (int j = 0; j <= e; ++j) {
                // new_dp[j] = average of dp[0..j]
                new_dp[j] = prefix[j] * inv[j + 1] % MOD;
            }
            dp.swap(new_dp);
        }

        // The contribution of this prime is dp[e] (starting from exponent e)
        ans = ans * dp[e] % MOD;
    }

    cout << ans << "\n";
    return 0;
