    a %= MOD;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int k;
    if (!(cin >> n >> k)) return 0;

    // Factorize n
    vector<pair<long long, int>> factors;
    long long temp = n;
    for (long long p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            int cnt = 0;
            while (temp % p == 0) {
                temp /= p;
                ++cnt;
            }
            factors.emplace_back(p, cnt);
        }
    }
    if (temp > 1) factors.emplace_back(temp, 1);

    long long ans = 1;
    for (auto [p, e] : factors) {
        // dp[i] = expected value of p^i after current steps? Actually we track expected value of the exponent part.
        // We need expected value of p^x after k steps starting from x = e.
        // The process: from current exponent x, choose uniformly a divisor of p^x, i.e., choose y uniformly from 0..x.
        // So new exponent is uniformly random in [0, x].
        // We want E[p^{X_k}].
        // We can compute DP over steps for the distribution of exponent, or directly compute expected value.
        // Let dp[t][i] = probability that exponent is i after t steps.
        // But k <= 10000, e <= log_2(1e15) ~ 50, so we can do DP on exponent values.

        vector<long long> dp(e + 1, 0);
        dp[e] = 1;
        for (int step = 0; step < k; ++step) {
            vector<long long> ndp(e + 1, 0);
            for (int i = 0; i <= e; ++i) {
                if (dp[i] == 0) continue;
                // from i, choose uniformly among 0..i
                long long inv = modpow(i + 1, MOD - 2);
                for (int j = 0; j <= i; ++j) {
                    ndp[j] = (ndp[j] + dp[i] * inv) % MOD;
                }
            }
            dp.swap(ndp);
        }
        long long exp_val = 0;
        long long p_pow = 1;
        for (int i = 0; i <= e; ++i) {
            exp_val = (exp_val + p_pow * dp[i]) % MOD;
            p_pow = p_pow * (p % MOD) % MOD;
        }
        ans = ans * exp_val % MOD;
    }

    cout << ans << "\n";
    return 0;
}
