    long long ans = 1;
    for (auto &fac : factors) {
        long long p = fac.first;
        int E = fac.second;

        // dp[e] = expected value of p^e after current step
        vector<long long> dp(E + 1);
        long long p_mod = p % MOD;
        long long cur = 1;
        for (int e = 0; e <= E; ++e) {
            dp[e] = cur;
            cur = cur * p_mod % MOD;
