        for (int i = 1; i <= E + 1; ++i) {
            inv[i] = mod_pow(i);
        }

        for (int step = 0; step < k; ++step) {
            // prefix sums of dp
            vector<long long> pref(E + 1);
            pref[0] = dp[0];
            for (int e = 1; e <= E; ++e) {
                pref[e] = (pref[e - 1] + dp[e]) % MOD;
            }
            // new dp values
            vector<long long> ndp(E + 1);
            for (int e = 0; e <= E; ++e) {
                ndp[e] = pref[e] * inv[e + 1] % MOD;
            }
            dp.swap(ndp);
        }

        ans = ans * dp[E] % MOD;
    }

    cout << ans << '\n';
    return 0;
